int cifs_tree_connect(unsigned int xid, struct cifs_ses *ses, const char *tree, struct cifs_tcon *tcon, const struct nls_table *cp) {
    int rc = 0;
    char *utf16_path = NULL;
    size_t utf16_len = 0;
    struct smb2_tree_connect_req *req = NULL;
    struct smb2_tree_connect_rsp *rsp = NULL;
    struct kvec iov[1];
    struct kvec rsp_iov;
    int resp_buftype;

    if (!ses || !tree || !tcon || !cp) {
        rc = -EINVAL;
        goto out;
    }

    rc = smb2_allocate_utf16_path(tree, cp, &utf16_path, &utf16_len);
    if (rc < 0)
        goto out;

    req = cifs_buf_get();
    if (!req) {
        rc = -ENOMEM;
        goto out_free_path;
    }

    iov[0].iov_base = req;
    iov[0].iov_len = get_req_buffer_size(req);

    rc = smb2_init_tree_connect_request(xid, ses, utf16_path, utf16_len, req);
    if (rc < 0)
        goto out_free_req;

    rc = cifs_call_async(ses, iov, 1, &rsp_iov, &resp_buftype, NULL, NULL, CIFS_TREE_CONNECT_OP, NULL);
    if (rc < 0)
        goto out_free_req;

    rsp = (struct smb2_tree_connect_rsp *)rsp_iov.iov_base;

    tcon->share_type = le16_to_cpu(rsp->ShareType);
    tcon->capabilities = le32_to_cpu(rsp->Capabilities);
    tcon->maximal_access = le32_to_cpu(rsp->MaximalAccess);

    if (resp_buftype != CIFS_NO_BUFFER)
        cifs_buf_release(rsp_iov.iov_base);

out_free_req:
    cifs_buf_release(req);
out_free_path:
    kfree(utf16_path);
out:
    if (rc < 0) {
        cifs_mark_net_name_bad(ses, tree);
        tcon->need_reconnect = 1;
    }

    return rc;
}

int cifs_tree_connect(unsigned int xid, struct cifs_ses *ses, const char *tree,
                      struct cifs_tcon *tcon, const struct nls_table *cp)
{
    int rc = 0;
    char *utf16_path = NULL;
    int utf16_path_len;
    struct smb2_tree_connect_req *req;
    struct smb2_tree_connect_rsp *rsp;

    if (!ses || !tcon || !tree) {
        rc = -EINVAL;
        goto out;
    }

    /* Allocate and prepare the UNC path in UTF-16 */
    utf16_path_len = cifs_str_to_utf16((__le16 *)utf16_path, tree, strlen(tree),
                                       &utf16_path_len, cp, false);
    if (utf16_path_len < 0) {
        rc = -ENOMEM;
        goto out;
    }

    /* Initialize the SMB2 tree connect request */
    req = cifs_smb2_init(SMB2_TREE_CONNECT, NULL, 0, NULL);
    if (!req) {
        rc = -ENOMEM;
        goto out;
    }

    req->path_offset = cpu_to_le16(offsetof(typeof(*req), buffer));
    req->path_length = cpu_to_le16(utf16_path_len * sizeof(__le16));
    memcpy(req->buffer, utf16_path, utf16_path_len * sizeof(__le16));

    /* Send the tree connect request to the server */
    rc = cifs_call_async(ses, tcon, (struct smb2_hdr *)req,
                         cifs_smb2_tree_connect_callback,
                         cifs_smb2_tree_connect_oplock_callback, NULL, 0, xid);
    if (rc < 0)
        goto out;

    /* Parse the response and update tcon structure */
    rsp = (struct smb2_tree_connect_rsp *)req;
    tcon->share_type = rsp->share_type;
    tcon->capabilities = le32_to_cpu(rsp->capabilities);
    tcon->maximal_access = le32_to_cpu(rsp->maximal_access);

    if (rsp->share_flags)
        tcon->share_flags = le32_to_cpu(rsp->share_flags);

    rc = 0;
out:
    if (utf16_path)
        kfree(utf16_path);
    if (rc < 0)
        cifs_mark_netname_bad(tcon, rc);

    return rc;
}

int cifs_tree_connect(unsigned int xid, struct cifs_ses *ses, const char *tree,
                      struct cifs_tcon *tcon, const struct nls_table *cp)
{
    int rc;
    int target_len;
    __le16 __user *utf16_path = NULL;
    char *full_path = NULL;
    struct smb2_tree_connect_request *req;
    struct smb2_tree_connect_response *resp;
    struct kvec iov[1];
    struct kvec resp_iov[1];
    int resp_buftype;

    if (!ses || !ses->server || !tree) {
        rc = -EINVAL;
        goto out;
    }

    target_len = strlen(tree) + 1;
    full_path = kmalloc(target_len, GFP_KERNEL);
    if (!full_path) {
        rc = -ENOMEM;
        goto out;
    }

    snprintf(full_path, target_len, "%s", tree);
    utf16_path = cifs_strndup_to_utf16(full_path, strlen(full_path), NULL, cp, true);
    if (!utf16_path) {
        rc = -ENOMEM;
        goto out;
    }

    req = kmalloc(sizeof(*req) + 2 * sizeof(__le16), GFP_KERNEL);
    if (!req) {
        rc = -ENOMEM;
        goto out;
    }

    iov[0].iov_base = req;
    iov[0].iov_len = sizeof(*req) + 2 * sizeof(__le16);

    rc = SMB2_init_msg(req);
    if (rc)
        goto out;

    req->structure_size = cpu_to_le16(16);
    req->path_offset = cpu_to_le16(16);
    req->path_length = cpu_to_le16(target_len * sizeof(__le16));
    memcpy(req->buffer, utf16_path, target_len * sizeof(__le16));

    rc = cifs_call_async(ses, 0, iov, 1, resp_iov, 1, 0, SMB2_OP_TREE_CONNECT, NULL, NULL);
    if (rc)
        goto out;

    resp = (struct smb2_tree_connect_response *)resp_iov[0].iov_base;
    if (resp->structure_size != cpu_to_le16(16)) {
        rc = -EINVAL;
        goto out;
    }

    tcon->share_type = le16_to_cpu(resp->share_type);
    tcon->maximal_access = le32_to_cpu(resp->maximal_access);
    tcon->capabilities = le32_to_cpu(resp->capabilities);

    rc = 0;

out:
    if (utf16_path)
        cifsConvertFree(utf16_path);
    if (full_path)
        kfree(full_path);
    if (req)
        kfree(req);

    return rc;
}

int cifs_tree_connect(unsigned int xid, struct cifs_ses *ses, const char *tree,
                      struct cifs_tcon *tcon, const struct nls_table *cp)
{
    int rc = 0;
    char *utf16_tree = NULL;
    wchar_t *utf16_path = NULL;
    char *full_path = NULL;
    int utf16_len;
    struct kveciov iov[2];
    struct smb2_tree_connect_req *req;
    struct smb2_tree_connect_rsp *rsp;

    if (!ses || !tree || !tcon || !cp) {
        rc = -EINVAL;
        goto out;
    }

    full_path = kmalloc(PATH_MAX, GFP_KERNEL);
    if (!full_path) {
        rc = -ENOMEM;
        goto out;
    }

    snprintf(full_path, PATH_MAX, "\\\\.\\%s", tree);

    utf16_len = cifs_str_to_utf16((__le16 **)&utf16_path, full_path,
                                   PATH_MAX, cp, NULL);
    if (utf16_len < 0) {
        rc = utf16_len;
        goto out;
    }

    iov[0].iov_base = req;
    iov[0].iov_len = sizeof(*req);
    iov[1].iov_base = utf16_path;
    iov[1].iov_len = utf16_len;

    rc = SMB2_tree_connect(ses, iov, 2, &rsp);
    if (rc) {
        if (rc != -ENOENT)
            ses->need_reconnect = 1;
        goto out;
    }

    tcon->share_type = rsp->share_type;
    tcon->capabilities = le32_to_cpu(rsp->capabilities);
    tcon->maximal_access = le32_to_cpu(rsp->maximal_access);
    tcon->fs_type = le32_to_cpu(rsp->fs_type);

    kfree(utf16_path);
    return 0;

out:
    kfree(utf16_path);
    kfree(full_path);
    return rc;
}

int cifs_tree_connect(unsigned int xid, struct cifs_ses *ses, const char *tree, struct cifs_tcon *tcon, const struct nls_table *cp) {
    int rc = 0;
    char *utf16_path = NULL;
    char *full_unc = NULL;

    if (!ses || !tree || !tcon || !cp)
        return -EINVAL;

    full_unc = kmalloc(PATH_MAX, GFP_KERNEL);
    if (!full_unc)
        return -ENOMEM;

    snprintf(full_unc, PATH_MAX, "\\\\%s\\%s", ses->serverName, tree);

    utf16_path = kmalloc(PATH_MAX * sizeof(__u16), GFP_KERNEL);
    if (!utf16_path) {
        kfree(full_unc);
        return -ENOMEM;
    }

    rc = cifsConvertToUTF16(utf16_path, full_unc, PATH_MAX, cp, 0);
    if (rc < 0)
        goto out;

    rc = SMB2_tree_connect(xid, ses, utf16_path, tcon);
    if (rc < 0)
        goto out;

    tcon->share_flags = le32_to_cpu(tcon->capabilities);
    tcon->max_path_depth = le32_to_cpu(tcon->max_path_depth);
    tcon->maximal_access = le32_to_cpu(tcon->maximal_access);

    if (tcon->capabilities & SMB2_SHARE_CAP_CONTINUOUS_AVAILABILITY)
        tcon->retry = 1;

    if (tcon->capabilities & SMB2_SHARE_CAP_DFS)
        tcon->dfs = 1;

out:
    kfree(utf16_path);
    kfree(full_unc);

    if (rc != 0) {
        tcon->tid = 0;
        cifs_reconnect_mark(tcon);
    }

    return rc;
}
